CREATE DATABASE IF NOT EXISTS careernest;
USE careernest;
CREATE TABLE IF NOT EXISTS students (id INT PRIMARY KEY,name VARCHAR(100) NOT NULL,branch VARCHAR(50) NOT NULL,cgpa DOUBLE NOT NULL,backlogs INT NOT NULL);
CREATE TABLE IF NOT EXISTS companies (id INT PRIMARY KEY,name VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id INT PRIMARY KEY,company_id INT NOT NULL,title VARCHAR(100) NOT NULL,branch VARCHAR(50) NOT NULL,min_cgpa DOUBLE NOT NULL,max_backlogs INT NOT NULL,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS applications (id INT PRIMARY KEY AUTO_INCREMENT,student_id INT NOT NULL,job_id INT NOT NULL,status VARCHAR(30) NOT NULL,UNIQUE(student_id,job_id),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE IF NOT EXISTS interviews (id INT PRIMARY KEY AUTO_INCREMENT,application_id INT NOT NULL,interview_date VARCHAR(20) NOT NULL,result VARCHAR(30) NOT NULL,FOREIGN KEY(application_id) REFERENCES applications(id));
